DOCKERFILE = """FROM python:latest
WORKDIR /app
COPY . .
RUN apt-get update && apt-get install -y curl
RUN pip install -r requirements.txt
ADD config.yaml /app/config.yaml
CMD ["python", "app.py"]
"""
lines = DOCKERFILE.replace("\\\n", " ").splitlines()
findings, copy_all_at, install_at, has_user = [], None, None, False
for i, line in enumerate(lines, 1):
    ins = line.split(None, 1)[0].upper() if line.strip() else ""
    if ins == "FROM" and (line.endswith(":latest") or ":" not in line.split()[1]):
        findings.append((i, "unpinned base image"))
    if ins == "ADD" and "http" not in line:
        findings.append((i, "use COPY instead of ADD"))
    if ins == "USER":
        has_user = True
    if "apt-get install" in line and "--no-install-recommends" not in line:
        findings.append((i, "apt-get install without --no-install-recommends"))
    if ins == "COPY" and line.split()[1:3] == [".", "."] and copy_all_at is None:
        copy_all_at = i
    if "pip install" in line and install_at is None:
        install_at = i
if copy_all_at and install_at and copy_all_at < install_at:
    findings.append((copy_all_at, "COPY . . before dependency install busts cache"))
if not has_user:
    findings.append((len(lines), "no USER, runs as root"))
for n, msg in sorted(findings):
    print(f"line {n}: {msg}")

import json
DATA = json.loads("""[
 {"Name": "/web", "RestartCount": 0, "State": {"Status": "running", "OOMKilled": false, "ExitCode": 0, "Health": {"Status": "healthy"}}},
 {"Name": "/worker", "RestartCount": 7, "State": {"Status": "restarting", "OOMKilled": false, "ExitCode": 1}},
 {"Name": "/cache", "RestartCount": 1, "State": {"Status": "exited", "OOMKilled": true, "ExitCode": 137}},
 {"Name": "/api", "RestartCount": 0, "State": {"Status": "running", "OOMKilled": false, "ExitCode": 0, "Health": {"Status": "unhealthy"}}}
]""")
for c in sorted(DATA, key=lambda c: c["Name"]):
    st = c["State"]
    reasons = []
    if st.get("Health", {}).get("Status") == "unhealthy":
        reasons.append("unhealthy")
    if c["RestartCount"] > 3:
        reasons.append(f"restarts={c['RestartCount']}")
    if st.get("OOMKilled"):
        reasons.append("oom-killed")
    if reasons:
        print(c["Name"].lstrip("/"), ", ".join(reasons))
